=== FILE: axil_timer.v ===
// axil_timer: AXI4-Lite timer peripheral with a level interrupt.
// Implements the microarchitecture spec for task prj-ada3a9b9d9:rtl-implementation.
// Single clock (aclk), synchronous active-low reset (aresetn).
// Supported ADDR_WIDTH: 4..8 (TMR-ADDR-WIDTH-RANGE).
`default_nettype none

module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

  localparam integer EXT_W       = 16;
  localparam [1:0]   RESP_OKAY   = 2'b00;
  localparam [1:0]   RESP_SLVERR = 2'b10;
  localparam [1:0]   IDX_CTRL    = 2'd0;
  localparam [1:0]   IDX_LOAD    = 2'd1;
  localparam [1:0]   IDX_COUNT   = 2'd2;
  localparam [1:0]   IDX_STATUS  = 2'd3;

  // ------------------------------------------------------------------
  // State registers (microarchitecture section 5)
  // ------------------------------------------------------------------
  reg                  aw_held_q;
  reg [ADDR_WIDTH-1:0] aw_addr_q;
  reg                  w_held_q;
  reg [31:0]           w_data_q;
  reg [3:0]            w_strb_q;
  reg                  bvalid_q;
  reg [1:0]            bresp_q;
  reg                  rvalid_q;
  reg [1:0]            rresp_q;
  reg [31:0]           rdata_q;
  reg                  en_q;
  reg                  ie_q;
  reg                  mode_q;
  reg [31:0]           load_q;
  reg [31:0]           count_q;
  reg                  expired_q;

  // ------------------------------------------------------------------
  // Handshakes (section 6.1, interface spec 3.2)
  // ------------------------------------------------------------------
  assign s_axil_awready = ~aw_held_q & ~bvalid_q;
  assign s_axil_wready  = ~w_held_q & ~bvalid_q;
  assign s_axil_arready = ~rvalid_q;

  wire aw_fire = s_axil_awvalid & s_axil_awready;
  wire w_fire  = s_axil_wvalid & s_axil_wready;
  wire wr_fire = (aw_fire & (w_fire | w_held_q)) | (w_fire & aw_held_q);
  wire ar_fire = s_axil_arvalid & s_axil_arready;

  wire [ADDR_WIDTH-1:0] wr_addr = aw_held_q ? aw_addr_q : s_axil_awaddr;
  wire [31:0]           wr_data = w_held_q ? w_data_q : s_axil_wdata;
  wire [3:0]            wr_strb = w_held_q ? w_strb_q : s_axil_wstrb;

  // ------------------------------------------------------------------
  // Decode (section 6.2): zero-extend to a fixed width so no part
  // select is empty at ADDR_WIDTH = 4.
  // ------------------------------------------------------------------
  wire [EXT_W-1:0] wr_ext    = {{(EXT_W-ADDR_WIDTH){1'b0}}, wr_addr};
  wire             wr_mapped = (wr_ext[1:0] == 2'b00) &
                               (wr_ext[EXT_W-1:4] == {(EXT_W-4){1'b0}});
  wire [1:0]       wr_idx    = wr_ext[3:2];
  wire             wr_ok     = wr_mapped & (wr_idx != IDX_COUNT);

  wire ctrl_we    = wr_fire & wr_mapped & (wr_idx == IDX_CTRL) & wr_strb[0];
  wire load_sel   = wr_fire & wr_mapped & (wr_idx == IDX_LOAD);
  wire status_clr = wr_fire & wr_mapped & (wr_idx == IDX_STATUS) &
                    wr_strb[0] & wr_data[0];

  wire [EXT_W-1:0] rd_ext    = {{(EXT_W-ADDR_WIDTH){1'b0}}, s_axil_araddr};
  wire             rd_mapped = (rd_ext[1:0] == 2'b00) &
                               (rd_ext[EXT_W-1:4] == {(EXT_W-4){1'b0}});

  reg [31:0] rd_val;
  always @* begin
    case (rd_ext[3:2])
      IDX_CTRL:   rd_val = {29'd0, mode_q, ie_q, en_q};
      IDX_LOAD:   rd_val = load_q;
      IDX_COUNT:  rd_val = count_q;
      IDX_STATUS: rd_val = {31'd0, expired_q};
      default:    rd_val = 32'd0;
    endcase
  end

  // ------------------------------------------------------------------
  // Bus next state
  // ------------------------------------------------------------------
  wire                  aw_held_d = wr_fire ? 1'b0 : (aw_fire ? 1'b1 : aw_held_q);
  wire [ADDR_WIDTH-1:0] aw_addr_d = aw_fire ? s_axil_awaddr : aw_addr_q;
  wire                  w_held_d  = wr_fire ? 1'b0 : (w_fire ? 1'b1 : w_held_q);
  wire [31:0]           w_data_d  = w_fire ? s_axil_wdata : w_data_q;
  wire [3:0]            w_strb_d  = w_fire ? s_axil_wstrb : w_strb_q;
  wire                  bvalid_d  = wr_fire ? 1'b1 :
                                    ((bvalid_q & s_axil_bready) ? 1'b0 : bvalid_q);
  wire [1:0]            bresp_d   = wr_fire ? (wr_ok ? RESP_OKAY : RESP_SLVERR) : bresp_q;
  wire                  rvalid_d  = ar_fire ? 1'b1 :
                                    ((rvalid_q & s_axil_rready) ? 1'b0 : rvalid_q);
  wire [1:0]            rresp_d   = ar_fire ? (rd_mapped ? RESP_OKAY : RESP_SLVERR) : rresp_q;
  wire [31:0]           rdata_d   = ar_fire ? (rd_mapped ? rd_val : 32'd0) : rdata_q;

  // ------------------------------------------------------------------
  // Timer datapath (section 8)
  // ------------------------------------------------------------------
  wire end_edge = en_q & (count_q[31:1] == 31'd0);
  wire start    = ctrl_we & wr_data[0];

  wire        en_d      = ctrl_we ? wr_data[0] :
                          ((end_edge & ~mode_q) ? 1'b0 : en_q);
  wire        ie_d      = ctrl_we ? wr_data[1] : ie_q;
  wire        mode_d    = ctrl_we ? wr_data[2] : mode_q;
  wire [31:0] count_d   = start    ? load_q :
                          end_edge ? (mode_q ? load_q : 32'd0) :
                          en_q     ? (count_q - 32'd1) :
                                     count_q;
  wire [31:0] load_d;
  assign load_d[7:0]   = (load_sel & wr_strb[0]) ? wr_data[7:0]   : load_q[7:0];
  assign load_d[15:8]  = (load_sel & wr_strb[1]) ? wr_data[15:8]  : load_q[15:8];
  assign load_d[23:16] = (load_sel & wr_strb[2]) ? wr_data[23:16] : load_q[23:16];
  assign load_d[31:24] = (load_sel & wr_strb[3]) ? wr_data[31:24] : load_q[31:24];
  wire        expired_d = end_edge ? 1'b1 : (status_clr ? 1'b0 : expired_q);

  // ------------------------------------------------------------------
  // Register block: reset value or q <= d
  // ------------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held_q <= 1'b0;
      aw_addr_q <= {ADDR_WIDTH{1'b0}};
      w_held_q  <= 1'b0;
      w_data_q  <= 32'd0;
      w_strb_q  <= 4'd0;
      bvalid_q  <= 1'b0;
      bresp_q   <= 2'b00;
      rvalid_q  <= 1'b0;
      rresp_q   <= 2'b00;
      rdata_q   <= 32'd0;
      en_q      <= 1'b0;
      ie_q      <= 1'b0;
      mode_q    <= 1'b0;
      load_q    <= 32'd0;
      count_q   <= 32'd0;
      expired_q <= 1'b0;
    end else begin
      aw_held_q <= aw_held_d;
      aw_addr_q <= aw_addr_d;
      w_held_q  <= w_held_d;
      w_data_q  <= w_data_d;
      w_strb_q  <= w_strb_d;
      bvalid_q  <= bvalid_d;
      bresp_q   <= bresp_d;
      rvalid_q  <= rvalid_d;
      rresp_q   <= rresp_d;
      rdata_q   <= rdata_d;
      en_q      <= en_d;
      ie_q      <= ie_d;
      mode_q    <= mode_d;
      load_q    <= load_d;
      count_q   <= count_d;
      expired_q <= expired_d;
    end
  end

  assign s_axil_bvalid = bvalid_q;
  assign s_axil_bresp  = bresp_q;
  assign s_axil_rvalid = rvalid_q;
  assign s_axil_rresp  = rresp_q;
  assign s_axil_rdata  = rdata_q;
  assign irq           = expired_q & ie_q;

`ifdef FORMAL
  // Design-intent properties (not submitted as a formal job).
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge aclk) f_past_valid <= 1'b1;

  always @(*) begin
    assert(!(aw_held_q && w_held_q));
    assert(!(bvalid_q && (aw_held_q || w_held_q)));
    assert(bresp_q == RESP_OKAY || bresp_q == RESP_SLVERR);
    assert(rresp_q == RESP_OKAY || rresp_q == RESP_SLVERR);
  end

  always @(posedge aclk) begin
    if (f_past_valid && aresetn && $past(aresetn)) begin
      if ($past(s_axil_bvalid && !s_axil_bready)) begin
        assert(s_axil_bvalid);
        assert(s_axil_bresp == $past(s_axil_bresp));
      end
      if ($past(s_axil_rvalid && !s_axil_rready)) begin
        assert(s_axil_rvalid);
        assert(s_axil_rdata == $past(s_axil_rdata));
        assert(s_axil_rresp == $past(s_axil_rresp));
      end
    end
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: tb_axil_timer.v ===
// Self-checking testbench for axil_timer (ADDR_WIDTH = 4 and 8).
`timescale 1ns/1ps
`default_nettype none

module tb_axil_timer;

  localparam [7:0] A_CTRL   = 8'h00;
  localparam [7:0] A_LOAD   = 8'h04;
  localparam [7:0] A_COUNT  = 8'h08;
  localparam [7:0] A_STATUS = 8'h0C;
  localparam [1:0] OKAY     = 2'b00;
  localparam [1:0] SLVERR   = 2'b10;

  reg        aclk;
  reg        aresetn;
  reg        sel;      // 0: ADDR_WIDTH=4 instance, 1: ADDR_WIDTH=8 instance
  reg [7:0]  awaddr;
  reg        awvalid;
  reg [31:0] wdata;
  reg [3:0]  wstrb;
  reg        wvalid;
  reg        bready;
  reg [7:0]  araddr;
  reg        arvalid;
  reg        rready;

  wire        awready4, wready4, bvalid4, arready4, rvalid4, irq4;
  wire [1:0]  bresp4, rresp4;
  wire [31:0] rdata4;
  wire        awready8, wready8, bvalid8, arready8, rvalid8, irq8;
  wire [1:0]  bresp8, rresp8;
  wire [31:0] rdata8;

  axil_timer #(.ADDR_WIDTH(4)) dut4 (
    .aclk(aclk), .aresetn(aresetn),
    .s_axil_awaddr(awaddr[3:0]), .s_axil_awvalid(awvalid & ~sel), .s_axil_awready(awready4),
    .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid & ~sel), .s_axil_wready(wready4),
    .s_axil_bresp(bresp4), .s_axil_bvalid(bvalid4), .s_axil_bready(bready & ~sel),
    .s_axil_araddr(araddr[3:0]), .s_axil_arvalid(arvalid & ~sel), .s_axil_arready(arready4),
    .s_axil_rdata(rdata4), .s_axil_rresp(rresp4), .s_axil_rvalid(rvalid4), .s_axil_rready(rready & ~sel),
    .irq(irq4)
  );

  axil_timer #(.ADDR_WIDTH(8)) dut8 (
    .aclk(aclk), .aresetn(aresetn),
    .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid & sel), .s_axil_awready(awready8),
    .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid & sel), .s_axil_wready(wready8),
    .s_axil_bresp(bresp8), .s_axil_bvalid(bvalid8), .s_axil_bready(bready & sel),
    .s_axil_araddr(araddr), .s_axil_arvalid(arvalid & sel), .s_axil_arready(arready8),
    .s_axil_rdata(rdata8), .s_axil_rresp(rresp8), .s_axil_rvalid(rvalid8), .s_axil_rready(rready & sel),
    .irq(irq8)
  );

  wire        awready = sel ? awready8 : awready4;
  wire        wready  = sel ? wready8  : wready4;
  wire        bvalid  = sel ? bvalid8  : bvalid4;
  wire [1:0]  bresp   = sel ? bresp8   : bresp4;
  wire        arready = sel ? arready8 : arready4;
  wire        rvalid  = sel ? rvalid8  : rvalid4;
  wire [1:0]  rresp   = sel ? rresp8   : rresp4;
  wire [31:0] rdata   = sel ? rdata8   : rdata4;
  wire        irq     = sel ? irq8     : irq4;

  initial aclk = 1'b0;
  always #5 aclk = ~aclk;

  integer passed;
  integer failed;
  integer cyc;               // number of rising edges so far
  reg     irq_log [0:16383]; // irq_log[n] = irq after edge n
  reg [8*64-1:0] nonce;

  always @(posedge aclk) begin
    irq_log[cyc % 16384] <= irq;
    cyc <= cyc + 1;
  end

  reg [31:0] last_rdata;
  reg [1:0]  last_rresp;
  reg [1:0]  last_bresp;
  integer    last_wr_edge;
  integer    last_rd_edge;

  // ---------------------------------------------------------------- helpers
  task check;
    input ok;
    input [8*64-1:0] msg;
    begin
      if (ok === 1'b1) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("FAIL sel=%0d cyc=%0d: %0s", sel, cyc, msg);
      end
    end
  endtask

  task check_eq;
    input [31:0] act;
    input [31:0] exp;
    input [8*64-1:0] msg;
    begin
      if (act === exp) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("FAIL sel=%0d cyc=%0d: %0s got 0x%08h exp 0x%08h", sel, cyc, msg, act, exp);
      end
    end
  endtask

  task check_resp;
    input [1:0] act;
    input [1:0] exp;
    input [8*64-1:0] msg;
    begin
      if (act === exp) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("FAIL sel=%0d cyc=%0d: %0s resp got %b exp %b", sel, cyc, msg, act, exp);
      end
    end
  endtask

  task check_irq;
    input integer e_idx;
    input exp;
    input [8*64-1:0] msg;
    begin
      if (irq_log[e_idx % 16384] === exp) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("FAIL sel=%0d: %0s irq after edge %0d got %b exp %b",
               sel, msg, e_idx, irq_log[e_idx % 16384], exp);
      end
    end
  endtask

  task tick;
    begin
      @(posedge aclk);
      #1;
    end
  endtask

  task wait_until;
    input integer target;
    begin
      while (cyc < target) tick;
    end
  endtask

  // AW and W together; bus must be idle. Completing edge -> last_wr_edge.
  task axi_write;
    input [7:0]  addr;
    input [31:0] data;
    input [3:0]  strb;
    integer guard;
    begin
      awaddr = addr; wdata = data; wstrb = strb;
      awvalid = 1'b1; wvalid = 1'b1; bready = 1'b1;
      guard = 0;
      while (!(awready === 1'b1 && wready === 1'b1) && guard < 100) begin
        tick;
        guard = guard + 1;
      end
      check(guard < 100, "write: ready timeout");
      tick;
      last_wr_edge = cyc;
      awvalid = 1'b0; wvalid = 1'b0;
      check(bvalid === 1'b1, "write: bvalid after completing edge");
      last_bresp = bresp;
      tick;
      check(bvalid === 1'b0, "write: bvalid low after bready edge");
    end
  endtask

  task axi_read;
    input [7:0] addr;
    integer guard;
    begin
      araddr = addr; arvalid = 1'b1; rready = 1'b1;
      guard = 0;
      while (!(arready === 1'b1) && guard < 100) begin
        tick;
        guard = guard + 1;
      end
      check(guard < 100, "read: arready timeout");
      tick;
      last_rd_edge = cyc;
      arvalid = 1'b0;
      check(rvalid === 1'b1, "read: rvalid after accept edge");
      last_rdata = rdata;
      last_rresp = rresp;
      tick;
      check(rvalid === 1'b0, "read: rvalid low after rready edge");
    end
  endtask

  task write_expect;
    input [7:0]  addr;
    input [31:0] data;
    input [3:0]  strb;
    input [1:0]  exp_resp;
    input [8*64-1:0] msg;
    begin
      axi_write(addr, data, strb);
      check_resp(last_bresp, exp_resp, msg);
    end
  endtask

  task read_expect;
    input [7:0]  addr;
    input [31:0] exp_data;
    input [1:0]  exp_resp;
    input [8*64-1:0] msg;
    begin
      axi_read(addr);
      check_eq(last_rdata, exp_data, msg);
      check_resp(last_rresp, exp_resp, msg);
    end
  endtask

  // COUNT read while a count started on start_edge with value base runs:
  // the read returns the value after edge (accept - 1).
  task read_count_lin;
    input [31:0] base;
    input integer start_edge;
    input [8*64-1:0] msg;
    begin
      axi_read(A_COUNT);
      check_eq(last_rdata, base - (last_rd_edge - 1 - start_edge), msg);
      check_resp(last_rresp, OKAY, msg);
    end
  endtask

  task do_reset;
    begin
      awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0;
      bready = 1'b0; rready = 1'b0;
      aresetn = 1'b0;
      tick;
      tick;
      check(bvalid === 1'b0, "reset: bvalid 0");
      check(rvalid === 1'b0, "reset: rvalid 0");
      check(irq === 1'b0, "reset: irq 0");
      check(awready === 1'b1, "reset: awready 1");
      check(wready === 1'b1, "reset: wready 1");
      check(arready === 1'b1, "reset: arready 1");
      aresetn = 1'b1;
      tick;
    end
  endtask

  // ---------------------------------------------------------------- suite
  task run_suite;
    integer E, C, S, R, k, t, e0, j;
    reg [31:0] v;
    begin
      // ---- reset values
      do_reset;
      read_expect(A_CTRL,   32'h0, OKAY, "reset CTRL");
      read_expect(A_LOAD,   32'h0, OKAY, "reset LOAD");
      read_expect(A_COUNT,  32'h0, OKAY, "reset COUNT");
      read_expect(A_STATUS, 32'h0, OKAY, "reset STATUS");

      // ---- register access, strobes, errors
      write_expect(A_CTRL, 32'hFFFF_FFF6, 4'hF, OKAY, "ctrl write");
      read_expect(A_CTRL, 32'h6, OKAY, "ctrl readback, reserved 0");
      read_expect(A_COUNT, 32'h0, OKAY, "EN=0 no start");
      write_expect(A_LOAD, 32'h1234_5678, 4'hF, OKAY, "load write");
      read_expect(A_LOAD, 32'h1234_5678, OKAY, "load readback");
      write_expect(A_LOAD, 32'hAABB_CCDD, 4'h5, OKAY, "load partial strobe");
      read_expect(A_LOAD, 32'h12BB_56DD, OKAY, "load partial readback");
      write_expect(A_LOAD, 32'hFFFF_FFFF, 4'h0, OKAY, "load empty strobe");
      read_expect(A_LOAD, 32'h12BB_56DD, OKAY, "load empty strobe readback");
      write_expect(A_CTRL, 32'h1, 4'hE, OKAY, "ctrl without strb0");
      read_expect(A_CTRL, 32'h6, OKAY, "ctrl unchanged without strb0");
      read_expect(A_COUNT, 32'h0, OKAY, "no start without strb0");
      write_expect(A_COUNT, 32'h55, 4'hF, SLVERR, "count write slverr");
      read_expect(A_COUNT, 32'h0, OKAY, "count unchanged by write");
      write_expect(A_CTRL, 32'h0, 4'h1, OKAY, "ctrl clear");
      read_expect(A_CTRL, 32'h0, OKAY, "ctrl cleared");
      write_expect(8'h01, 32'hFFFF_FFFF, 4'hF, SLVERR, "misaligned write 0x1");
      read_expect(A_CTRL, 32'h0, OKAY, "no alias from 0x1");
      write_expect(8'h06, 32'hFFFF_FFFF, 4'hF, SLVERR, "misaligned write 0x6");
      read_expect(A_LOAD, 32'h12BB_56DD, OKAY, "no alias from 0x6");
      read_expect(8'h02, 32'h0, SLVERR, "misaligned read 0x2");
      read_expect(8'h07, 32'h0, SLVERR, "misaligned read 0x7");
      write_expect(A_STATUS, 32'hFFFF_FFFE, 4'hF, OKAY, "status write no clear");
      read_expect(A_STATUS, 32'h0, OKAY, "status still 0");
      if (sel) begin
        write_expect(8'h10, 32'hFFFF_FFFF, 4'hF, SLVERR, "unmapped write 0x10");
        read_expect(A_CTRL, 32'h0, OKAY, "no alias from 0x10");
        write_expect(8'h14, 32'h0, 4'hF, SLVERR, "unmapped write 0x14");
        read_expect(A_LOAD, 32'h12BB_56DD, OKAY, "no alias from 0x14");
        read_expect(8'h14, 32'h0, SLVERR, "unmapped read 0x14");
        read_expect(8'h18, 32'h0, SLVERR, "unmapped read 0x18");
        read_expect(8'h1C, 32'h0, SLVERR, "unmapped read 0x1C");
        read_expect(8'h80, 32'h0, SLVERR, "unmapped read 0x80");
        read_expect(8'h8C, 32'h0, SLVERR, "unmapped read 0x8C");
        read_expect(8'hFC, 32'h0, SLVERR, "unmapped read 0xFC");
      end
      check(irq === 1'b0, "irq low after register tests");

      // ---- one-shot count length and irq
      write_expect(A_LOAD, 32'd5, 4'hF, OKAY, "T2 load 5");
      write_expect(A_CTRL, 32'h3, 4'h1, OKAY, "T2 start oneshot IE");
      E = last_wr_edge;
      wait_until(E + 8);
      for (k = 0; k < 8; k = k + 1) check_irq(E + k, (k >= 5), "T2 oneshot end at E+5");
      read_expect(A_CTRL, 32'h2, OKAY, "T2 EN cleared by end");
      read_expect(A_COUNT, 32'h0, OKAY, "T2 COUNT 0 after end");
      read_expect(A_STATUS, 32'h1, OKAY, "T2 EXPIRED set");
      write_expect(A_STATUS, 32'h0, 4'h1, OKAY, "T2 status write 0");
      read_expect(A_STATUS, 32'h1, OKAY, "T2 write 0 no clear");
      write_expect(A_STATUS, 32'h1, 4'h2, OKAY, "T2 status no strb0");
      read_expect(A_STATUS, 32'h1, OKAY, "T2 no strb0 no clear");
      write_expect(A_CTRL, 32'h0, 4'h1, OKAY, "T2 IE off");
      C = last_wr_edge;
      check_irq(C - 1, 1'b1, "T2 irq before IE off");
      check_irq(C, 1'b0, "T2 irq drops on IE off edge");
      write_expect(A_CTRL, 32'h2, 4'h1, OKAY, "T2 IE on");
      C = last_wr_edge;
      check_irq(C - 1, 1'b0, "T2 irq before IE on");
      check_irq(C, 1'b1, "T2 irq rises on IE on edge");
      read_expect(A_COUNT, 32'h0, OKAY, "T2 EN=0 write no start");
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T2 status clear");
      C = last_wr_edge;
      check_irq(C - 1, 1'b1, "T2 irq before clear");
      check_irq(C, 1'b0, "T2 irq drops on clear edge");
      read_expect(A_STATUS, 32'h0, OKAY, "T2 status cleared");
      wait_until(cyc + 10);
      read_expect(A_STATUS, 32'h0, OKAY, "T2 no further oneshot expiry");

      // ---- COUNT reads, running undisturbed
      write_expect(A_LOAD, 32'd40, 4'hF, OKAY, "T3 load 40");
      write_expect(A_CTRL, 32'h1, 4'h1, OKAY, "T3 start");
      E = last_wr_edge;
      read_count_lin(32'd40, E, "T3 count read");
      write_expect(A_LOAD, 32'd100, 4'hF, OKAY, "T3 load write while running");
      read_count_lin(32'd40, E, "T3 load write leaves count");
      read_expect(A_LOAD, 32'd100, OKAY, "T3 load readback");
      write_expect(A_COUNT, 32'h0, 4'hF, SLVERR, "T3 count write slverr");
      read_count_lin(32'd40, E, "T3 count write undisturbed");
      write_expect(8'h03, 32'hFFFF_FFFF, 4'hF, SLVERR, "T3 unmapped write");
      read_count_lin(32'd40, E, "T3 unmapped write undisturbed");
      write_expect(A_STATUS, 32'h0, 4'hF, OKAY, "T3 status no clear");
      read_count_lin(32'd40, E, "T3 status write undisturbed");
      read_expect(A_CTRL, 32'h1, OKAY, "T3 still running");
      wait_until(E + 42);
      read_expect(A_STATUS, 32'h1, OKAY, "T3 expired after 40");
      read_expect(A_COUNT, 32'h0, OKAY, "T3 count 0 after end");
      read_expect(A_CTRL, 32'h0, OKAY, "T3 EN 0 after end");
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T3 clear");
      read_expect(A_STATUS, 32'h0, OKAY, "T3 cleared");

      // ---- restart and stop
      write_expect(A_CTRL, 32'h1, 4'h1, OKAY, "T4 start load 100");
      E = last_wr_edge;
      read_count_lin(32'd100, E, "T4 count");
      write_expect(A_CTRL, 32'h1, 4'h1, OKAY, "T4 restart");
      E = last_wr_edge;
      read_count_lin(32'd100, E, "T4 count after restart");
      write_expect(A_CTRL, 32'h0, 4'h1, OKAY, "T4 stop");
      S = last_wr_edge;
      v = 32'd100 - (S - E);
      read_expect(A_COUNT, v, OKAY, "T4 count after stop edge");
      wait_until(cyc + 5);
      read_expect(A_COUNT, v, OKAY, "T4 count held");
      read_expect(A_CTRL, 32'h0, OKAY, "T4 EN 0");
      write_expect(A_CTRL, 32'h0, 4'h1, OKAY, "T4 stop again");
      read_expect(A_COUNT, v, OKAY, "T4 stop while stopped");
      read_expect(A_STATUS, 32'h0, OKAY, "T4 no expiry");

      // ---- periodic
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T5 clear");
      write_expect(A_LOAD, 32'd4, 4'hF, OKAY, "T5 load 4");
      write_expect(A_CTRL, 32'h7, 4'h1, OKAY, "T5 start periodic");
      E = last_wr_edge;
      wait_until(E + 14);
      for (k = 0; k < 14; k = k + 1) check_irq(E + k, (k >= 4), "T5 first end at E+4");
      for (k = 0; k < 3; k = k + 1) begin
        axi_read(A_COUNT);
        t = last_rd_edge - 1;
        check_eq(last_rdata, 4 - ((t - E) % 4), "T5 periodic count");
      end
      read_expect(A_CTRL, 32'h7, OKAY, "T5 EN stays 1");
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T5 clear while periodic");
      C = last_wr_edge;
      e0 = E + 4 * ((C - E + 3) / 4);
      wait_until(C + 12);
      for (t = C; t < C + 12; t = t + 1) check_irq(t, (t >= e0), "T5 periodic re-expiry");

      // ---- LOAD = 0
      write_expect(A_CTRL, 32'h2, 4'h1, OKAY, "T6 stop");
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T6 clear");
      read_expect(A_STATUS, 32'h0, OKAY, "T6 cleared");
      write_expect(A_LOAD, 32'd0, 4'hF, OKAY, "T6 load 0");
      write_expect(A_CTRL, 32'h3, 4'h1, OKAY, "T6 oneshot load 0");
      E = last_wr_edge;
      wait_until(E + 4);
      check_irq(E, 1'b0, "T6 no expiry on start edge");
      check_irq(E + 1, 1'b1, "T6 load0 ends at E+1");
      read_expect(A_CTRL, 32'h2, OKAY, "T6 oneshot stopped");
      read_expect(A_COUNT, 32'h0, OKAY, "T6 count 0");
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T6 clear 2");
      read_expect(A_STATUS, 32'h0, OKAY, "T6 cleared 2");
      write_expect(A_CTRL, 32'h7, 4'h1, OKAY, "T6 periodic load 0");
      E = last_wr_edge;
      wait_until(E + 6);
      check_irq(E, 1'b0, "T6p no expiry on start edge");
      for (k = 1; k < 6; k = k + 1) check_irq(E + k, 1'b1, "T6p ends every edge");
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T6p clear on end edge");
      C = last_wr_edge;
      check_irq(C, 1'b1, "T6p end beats clear");
      read_expect(A_STATUS, 32'h1, OKAY, "T6p status stays set");
      read_expect(A_COUNT, 32'h0, OKAY, "T6p count 0");
      read_expect(A_CTRL, 32'h7, OKAY, "T6p running");
      write_expect(A_CTRL, 32'h0, 4'h1, OKAY, "T6p stop");
      read_expect(A_COUNT, 32'h0, OKAY, "T6p count after stop");
      read_expect(A_CTRL, 32'h0, OKAY, "T6p stopped");
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T6p clear");
      read_expect(A_STATUS, 32'h0, OKAY, "T6p cleared");

      // ---- CTRL write on end edge
      write_expect(A_LOAD, 32'd6, 4'hF, OKAY, "T7 load 6");
      write_expect(A_CTRL, 32'h3, 4'h1, OKAY, "T7a start");
      E = last_wr_edge;
      wait_until(E + 5);
      write_expect(A_CTRL, 32'h3, 4'h1, OKAY, "T7a restart on end edge");
      C = last_wr_edge;
      check(C == E + 6, "T7a write landed on end edge");
      check_irq(E + 5, 1'b0, "T7a no early expiry");
      check_irq(E + 6, 1'b1, "T7a expired on end edge");
      read_count_lin(32'd6, E + 6, "T7a count restarted");
      read_expect(A_CTRL, 32'h3, OKAY, "T7a EN stays 1");
      wait_until(E + 15);
      read_expect(A_CTRL, 32'h2, OKAY, "T7a second end stops");
      read_expect(A_COUNT, 32'h0, OKAY, "T7a count 0");
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T7b clear");
      write_expect(A_CTRL, 32'h3, 4'h1, OKAY, "T7b start");
      E = last_wr_edge;
      wait_until(E + 5);
      write_expect(A_CTRL, 32'h2, 4'h1, OKAY, "T7b stop on end edge");
      C = last_wr_edge;
      check(C == E + 6, "T7b write landed on end edge");
      check_irq(E + 5, 1'b0, "T7b no early expiry");
      check_irq(E + 6, 1'b1, "T7b expired on end edge");
      read_expect(A_CTRL, 32'h2, OKAY, "T7b EN 0");
      read_expect(A_COUNT, 32'h0, OKAY, "T7b count 0 (oneshot)");
      read_expect(A_STATUS, 32'h1, OKAY, "T7b status set");
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T7c clear");
      write_expect(A_CTRL, 32'h7, 4'h1, OKAY, "T7c start periodic");
      E = last_wr_edge;
      wait_until(E + 5);
      write_expect(A_CTRL, 32'h2, 4'h1, OKAY, "T7c stop on end edge");
      C = last_wr_edge;
      check(C == E + 6, "T7c write landed on end edge");
      check_irq(E + 5, 1'b0, "T7c no early expiry");
      check_irq(E + 6, 1'b1, "T7c expired on end edge");
      read_expect(A_COUNT, 32'd6, OKAY, "T7c count = LOAD (pre-edge MODE 1)");
      wait_until(cyc + 3);
      read_expect(A_COUNT, 32'd6, OKAY, "T7c count held");
      read_expect(A_CTRL, 32'h2, OKAY, "T7c EN 0 MODE 0");
      read_expect(A_STATUS, 32'h1, OKAY, "T7c status set");

      // ---- STATUS clear on end edge
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T8a clear");
      write_expect(A_LOAD, 32'd5, 4'hF, OKAY, "T8a load 5");
      write_expect(A_CTRL, 32'h3, 4'h1, OKAY, "T8a start");
      E = last_wr_edge;
      wait_until(E + 4);
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T8a clear on end edge");
      C = last_wr_edge;
      check(C == E + 5, "T8a clear landed on end edge");
      check_irq(E + 5, 1'b1, "T8a end beats clear irq");
      read_expect(A_STATUS, 32'h1, OKAY, "T8a status stays set");
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T8b clear");
      write_expect(A_LOAD, 32'd8, 4'hF, OKAY, "T8b load 8");
      write_expect(A_CTRL, 32'h7, 4'h1, OKAY, "T8b start periodic");
      E = last_wr_edge;
      wait_until(E + 7);
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T8b clear on end edge");
      C = last_wr_edge;
      check(C == E + 8, "T8b clear landed on end edge");
      read_expect(A_STATUS, 32'h1, OKAY, "T8b status stays set");
      write_expect(A_CTRL, 32'h0, 4'h1, OKAY, "T8b stop");
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T8b clear after stop");
      read_expect(A_STATUS, 32'h0, OKAY, "T8b cleared");

      // ---- LOAD write on periodic end edge (open choice: accept both)
      write_expect(A_LOAD, 32'd3, 4'hF, OKAY, "T9 load 3");
      write_expect(A_CTRL, 32'h5, 4'h1, OKAY, "T9 start periodic");
      E = last_wr_edge;
      wait_until(E + 2);
      write_expect(A_LOAD, 32'd7, 4'hF, OKAY, "T9 load on end edge");
      C = last_wr_edge;
      check(C == E + 3, "T9 load write landed on end edge");
      axi_read(A_COUNT);
      j = last_rd_edge - 1 - C;
      check(j >= 0 && j < 3, "T9 read timing");
      check(last_rdata == (3 - j) || last_rdata == (7 - j), "T9 old or new LOAD reload");
      write_expect(A_CTRL, 32'h0, 4'h1, OKAY, "T9 stop");

      // ---- restart changes MODE
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T10 clear");
      write_expect(A_LOAD, 32'd4, 4'hF, OKAY, "T10 load 4");
      write_expect(A_CTRL, 32'h7, 4'h1, OKAY, "T10 start periodic");
      E = last_wr_edge;
      wait_until(E + 1);
      write_expect(A_CTRL, 32'h3, 4'h1, OKAY, "T10 restart oneshot");
      S = last_wr_edge;
      check(S == E + 2, "T10 restart edge");
      wait_until(S + 6);
      for (t = E; t < S + 4; t = t + 1) check_irq(t, 1'b0, "T10 no end before S+4");
      check_irq(S + 4, 1'b1, "T10 end at S+4");
      check_irq(S + 5, 1'b1, "T10 irq held");
      read_expect(A_CTRL, 32'h2, OKAY, "T10 oneshot stopped");
      read_expect(A_COUNT, 32'h0, OKAY, "T10 count 0");
      write_expect(A_STATUS, 32'h1, 4'h1, OKAY, "T10 clear 2");
      wait_until(cyc + 12);
      read_expect(A_STATUS, 32'h0, OKAY, "T10 no further ends");

      // ---- 32-bit counter
      write_expect(A_LOAD, 32'h0000_0102, 4'hF, OKAY, "T11 load 0x102");
      write_expect(A_CTRL, 32'h1, 4'h1, OKAY, "T11 start");
      E = last_wr_edge;
      read_count_lin(32'h0000_0102, E, "T11 count borrow a");
      read_count_lin(32'h0000_0102, E, "T11 count borrow b");
      read_count_lin(32'h0000_0102, E, "T11 count borrow c");
      write_expect(A_CTRL, 32'h0, 4'h1, OKAY, "T11 stop");
      write_expect(A_LOAD, 32'h8000_0001, 4'hF, OKAY, "T11 load 0x80000001");
      write_expect(A_CTRL, 32'h1, 4'h1, OKAY, "T11 start high");
      E = last_wr_edge;
      wait_until(E + 10);
      read_expect(A_STATUS, 32'h0, OKAY, "T11 high bit keeps running");
      read_count_lin(32'h8000_0001, E, "T11 count high");
      write_expect(A_CTRL, 32'h0, 4'h1, OKAY, "T11 stop high");

      // ---- write channel ordering, B back-pressure
      awaddr = A_LOAD; awvalid = 1'b1; wvalid = 1'b0; bready = 1'b0;
      check(awready === 1'b1, "T12a awready idle");
      tick;
      awvalid = 1'b0;
      check(awready === 1'b0, "T12a aw held blocks awready");
      check(wready === 1'b1, "T12a wready while aw held");
      check(bvalid === 1'b0, "T12a no B before W");
      tick;
      tick;
      check(bvalid === 1'b0, "T12a still no B");
      check(awready === 1'b0, "T12a awready still 0");
      wdata = 32'hCAFE_F00D; wstrb = 4'hF; wvalid = 1'b1;
      tick;
      wvalid = 1'b0;
      check(bvalid === 1'b1, "T12a B after W");
      check_resp(bresp, OKAY, "T12a bresp");
      check(awready === 1'b0, "T12a awready 0 while B");
      check(wready === 1'b0, "T12a wready 0 while B");
      awaddr = A_STATUS; wdata = 32'h0; wstrb = 4'hF; awvalid = 1'b1; wvalid = 1'b1;
      for (k = 0; k < 3; k = k + 1) begin
        tick;
        check(bvalid === 1'b1, "T12a bvalid held under stall");
        check_resp(bresp, OKAY, "T12a bresp stable");
        check(awready === 1'b0, "T12a no AW accept under stall");
        check(wready === 1'b0, "T12a no W accept under stall");
      end
      bready = 1'b1;
      tick;
      check(bvalid === 1'b0, "T12a B drained");
      check(awready === 1'b1, "T12a awready after drain");
      check(wready === 1'b1, "T12a wready after drain");
      tick;
      awvalid = 1'b0; wvalid = 1'b0;
      check(bvalid === 1'b1, "T12a second write B");
      check_resp(bresp, OKAY, "T12a second bresp");
      tick;
      check(bvalid === 1'b0, "T12a second B drained");
      tick;
      tick;
      check(bvalid === 1'b0, "T12a exactly one B each");
      read_expect(A_LOAD, 32'hCAFE_F00D, OKAY, "T12a AW-first data");

      axi_read(A_COUNT);
      v = last_rdata;
      wdata = 32'h0000_1234; wstrb = 4'hF; wvalid = 1'b1; awvalid = 1'b0; bready = 1'b1;
      tick;
      wvalid = 1'b0;
      check(wready === 1'b0, "T12b w held blocks wready");
      check(awready === 1'b1, "T12b awready while w held");
      check(bvalid === 1'b0, "T12b no B before AW");
      tick;
      check(bvalid === 1'b0, "T12b still no B");
      awaddr = A_COUNT; awvalid = 1'b1;
      tick;
      awvalid = 1'b0;
      check(bvalid === 1'b1, "T12b B after AW");
      check_resp(bresp, SLVERR, "T12b count write slverr");
      tick;
      check(bvalid === 1'b0, "T12b B drained");
      read_expect(A_COUNT, v, OKAY, "T12b count unchanged");

      wdata = 32'h0BAD_BEEF; wstrb = 4'h3; wvalid = 1'b1;
      tick;
      wvalid = 1'b0;
      check(bvalid === 1'b0, "T12c no B before AW");
      awaddr = A_LOAD; awvalid = 1'b1; wdata = 32'hFFFF_FFFF; wstrb = 4'hF;
      tick;
      awvalid = 1'b0;
      check(bvalid === 1'b1, "T12c B after AW");
      check_resp(bresp, OKAY, "T12c bresp");
      tick;
      read_expect(A_LOAD, 32'hCAFE_BEEF, OKAY, "T12c held data and strobes");

      // ---- R back-pressure and snapshot
      write_expect(A_LOAD, 32'd50, 4'hF, OKAY, "T13 load 50");
      write_expect(A_CTRL, 32'h1, 4'h1, OKAY, "T13 start");
      E = last_wr_edge;
      araddr = A_COUNT; arvalid = 1'b1; rready = 1'b0;
      check(arready === 1'b1, "T13 arready idle");
      tick;
      arvalid = 1'b0;
      R = cyc;
      v = 32'd50 - (R - 1 - E);
      check(rvalid === 1'b1, "T13 rvalid");
      check_eq(rdata, v, "T13 count snapshot");
      check_resp(rresp, OKAY, "T13 rresp");
      check(arready === 1'b0, "T13 arready 0 while R");
      araddr = A_LOAD; arvalid = 1'b1;
      for (k = 0; k < 4; k = k + 1) begin
        tick;
        check(rvalid === 1'b1, "T13 rvalid held");
        check_eq(rdata, v, "T13 rdata stable while counting");
        check_resp(rresp, OKAY, "T13 rresp stable");
        check(arready === 1'b0, "T13 no AR accept under stall");
      end
      axi_write(A_LOAD, 32'h77, 4'hF);
      check_resp(last_bresp, OKAY, "T13 write during R stall");
      check(rvalid === 1'b1, "T13 rvalid held after write");
      check_eq(rdata, v, "T13 rdata not refreshed");
      rready = 1'b1;
      tick;
      check(rvalid === 1'b0, "T13 R drained");
      check(arready === 1'b1, "T13 arready after drain");
      tick;
      arvalid = 1'b0;
      check(rvalid === 1'b1, "T13 queued AR served");
      check_eq(rdata, 32'h77, "T13 load after stall");
      check_resp(rresp, OKAY, "T13 rresp 2");
      tick;
      check(rvalid === 1'b0, "T13 R drained 2");
      write_expect(A_CTRL, 32'h0, 4'h1, OKAY, "T13 stop");

      // ---- read and write on the same edge
      write_expect(A_LOAD, 32'h1111_1111, 4'hF, OKAY, "T14 load");
      awaddr = A_LOAD; wdata = 32'h2222_2222; wstrb = 4'hF;
      awvalid = 1'b1; wvalid = 1'b1; bready = 1'b1;
      araddr = A_LOAD; arvalid = 1'b1; rready = 1'b1;
      check(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, "T14 all ready");
      tick;
      awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0;
      check(bvalid === 1'b1, "T14 bvalid");
      check_resp(bresp, OKAY, "T14 bresp");
      check(rvalid === 1'b1, "T14 rvalid");
      check_eq(rdata, 32'h1111_1111, "T14 read pre-edge value");
      check_resp(rresp, OKAY, "T14 rresp");
      tick;
      check(bvalid === 1'b0, "T14 B one cycle");
      check(rvalid === 1'b0, "T14 R one cycle");
      read_expect(A_LOAD, 32'h2222_2222, OKAY, "T14 write took effect");

      // ---- reset during traffic
      write_expect(A_LOAD, 32'd10, 4'hF, OKAY, "T15 load 10");
      write_expect(A_CTRL, 32'h7, 4'h1, OKAY, "T15 start periodic IE");
      E = last_wr_edge;
      wait_until(E + 12);
      check(irq === 1'b1, "T15 irq before reset");
      awaddr = A_STATUS; wdata = 32'h0; wstrb = 4'hF; awvalid = 1'b1; wvalid = 1'b1; bready = 1'b0;
      tick;
      awvalid = 1'b0; wvalid = 1'b0;
      check(bvalid === 1'b1, "T15 B pending");
      araddr = A_LOAD; arvalid = 1'b1; rready = 1'b0;
      tick;
      arvalid = 1'b0;
      check(rvalid === 1'b1, "T15 R pending");
      aresetn = 1'b0;
      tick;
      check(bvalid === 1'b0, "T15 reset clears bvalid");
      check(rvalid === 1'b0, "T15 reset clears rvalid");
      check(irq === 1'b0, "T15 reset clears irq");
      check(awready === 1'b1, "T15 awready after reset");
      check(wready === 1'b1, "T15 wready after reset");
      check(arready === 1'b1, "T15 arready after reset");
      aresetn = 1'b1;
      read_expect(A_CTRL, 32'h0, OKAY, "T15 CTRL reset");
      read_expect(A_LOAD, 32'h0, OKAY, "T15 LOAD reset");
      read_expect(A_COUNT, 32'h0, OKAY, "T15 COUNT reset");
      read_expect(A_STATUS, 32'h0, OKAY, "T15 STATUS reset");
      wait_until(cyc + 15);
      read_expect(A_STATUS, 32'h0, OKAY, "T15 stopped after reset");
      read_expect(A_COUNT, 32'h0, OKAY, "T15 count stays 0");

      // aw_held cleared by reset
      awaddr = A_STATUS; wdata = 32'h0; wstrb = 4'hF; awvalid = 1'b1; wvalid = 1'b0; bready = 1'b1;
      tick;
      awvalid = 1'b0;
      check(awready === 1'b0, "T15 aw held");
      aresetn = 1'b0;
      tick;
      aresetn = 1'b1;
      check(awready === 1'b1, "T15 reset clears aw_held");
      check(bvalid === 1'b0, "T15 no B after reset");
      wvalid = 1'b1;
      tick;
      wvalid = 1'b0;
      check(bvalid === 1'b0, "T15 W alone after reset no B");
      check(wready === 1'b0, "T15 w held");
      check(awready === 1'b1, "T15 awready with w held");
      awvalid = 1'b1;
      tick;
      awvalid = 1'b0;
      check(bvalid === 1'b1, "T15 write completes");
      check_resp(bresp, OKAY, "T15 bresp");
      tick;
      check(bvalid === 1'b0, "T15 B drained");

      // w_held cleared by reset
      wvalid = 1'b1;
      tick;
      wvalid = 1'b0;
      check(wready === 1'b0, "T15 w held 2");
      aresetn = 1'b0;
      tick;
      aresetn = 1'b1;
      check(wready === 1'b1, "T15 reset clears w_held");
      awvalid = 1'b1;
      tick;
      awvalid = 1'b0;
      check(bvalid === 1'b0, "T15 AW alone after reset no B");
      check(awready === 1'b0, "T15 aw held 2");
      check(wready === 1'b1, "T15 wready with aw held");
      wvalid = 1'b1;
      tick;
      wvalid = 1'b0;
      check(bvalid === 1'b1, "T15 write completes 2");
      tick;
      check(bvalid === 1'b0, "T15 B drained 2");
    end
  endtask

  // ---------------------------------------------------------------- main
  initial begin
    passed = 0;
    failed = 0;
    cyc = 0;
    nonce = "none";
    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
    aresetn = 1'b0;
    sel = 1'b0;
    awaddr = 8'h0; awvalid = 1'b0; wdata = 32'h0; wstrb = 4'h0; wvalid = 1'b0; bready = 1'b0;
    araddr = 8'h0; arvalid = 1'b0; rready = 1'b0;
    last_rdata = 32'h0; last_rresp = 2'b00; last_bresp = 2'b00;
    last_wr_edge = 0; last_rd_edge = 0;

    sel = 1'b0;
    run_suite;
    sel = 1'b1;
    run_suite;

    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

  initial begin
    #5000000;
    failed = failed + 1;
    $error("FAIL: watchdog timeout");
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule

`default_nettype wire
